import { getCustomer, TIER_DISCOUNTS, normalizeId } from './customers.js';
import { getProduct } from './catalogue.js';
import { ok, fail } from './result.js';
import { nextInvoiceNumber } from './numbering.js';
import { roundCents } from './money.js';
import { isValidDate, addDays } from './dates.js';

/**
 * Create a new invoice.
 * @param {{ customerId: string, issueDate: string, lines: Array<{ sku: string, qty: number }> }} param0
 * @returns {{ ok: true, value: { customerId: string, issueDate: string, status: string, lines: Array } } | { ok: false, error: string }}
 */
export function createInvoice({ customerId, issueDate, lines, terms }) {
  // Normalize customer ID
  const normalizedCustomerId = normalizeId(customerId);

  // Validate customer exists
  const customerResult = getCustomer(normalizedCustomerId);
  if (!customerResult.ok) return customerResult;

  const customer = customerResult.value;

  // Validate issueDate is a real date in YYYY-MM-DD format
  if (!isValidDate(issueDate)) return fail('DATE_INVALID');

  // Determine and validate terms (default NET30)
  const finalTerms = terms ?? 'NET30';
  if (!['NET14', 'NET30', 'EOM'].includes(finalTerms)) {
    return fail('TERMS_INVALID');
  }

  // Calculate due date
  let dueDate;
  if (finalTerms === 'NET14') {
    dueDate = addDays(issueDate, 14);
  } else if (finalTerms === 'NET30') {
    dueDate = addDays(issueDate, 30);
  } else if (finalTerms === 'EOM') {
    // Last day of the issue date's month
    const d = new Date(issueDate + 'T00:00:00Z');
    d.setUTCMonth(d.getUTCMonth() + 1, 0);
    dueDate = d.toISOString().slice(0, 10);
  }

  // Validate lines is not empty
  if (!Array.isArray(lines) || lines.length === 0) return fail('NO_LINES');

  // Build invoice lines
  const invoiceLines = [];
  for (const line of lines) {
    // Validate qty is a positive integer
    if (!Number.isInteger(line.qty) || line.qty <= 0) return fail('QTY_INVALID');

    // Determine discountPercent: explicit value wins, otherwise use tier discount
    let discountPercent;
    if ('discountPercent' in line) {
      discountPercent = line.discountPercent;
    } else {
      discountPercent = TIER_DISCOUNTS[customer.tier];
    }

    // Validate discountPercent
    if (typeof discountPercent !== 'number' || discountPercent < 0 || discountPercent > 100) {
      return fail('DISCOUNT_INVALID');
    }

    // Get product by SKU
    const productResult = getProduct(line.sku);
    if (!productResult.ok) return productResult;

    const product = productResult.value;
    invoiceLines.push({
      sku: line.sku,
      name: product.name,
      qty: line.qty,
      unitPrice: product.unitPrice,
      vatRate: product.vatRate,
      discountPercent,
    });
  }

  return ok({
    customerId: normalizedCustomerId,
    issueDate,
    terms: finalTerms,
    dueDate,
    status: 'draft',
    lines: invoiceLines,
  });
}

/**
 * Calculate the total for a line item (qty times unitPrice).
 * @param {{ qty: number, unitPrice: number }} line
 * @returns {number}
 */
export function lineTotal(line) {
  return line.qty * line.unitPrice;
}

/**
 * Calculate the invoice totals.
 * @param {{ lines: Array<{ qty: number, unitPrice: number, discountPercent?: number, vatRate?: number }> }} invoice
 * @returns {{ ok: true, value: { subtotal: number, discount: number, vat: number, total: number } } | { ok: false, error: string }}
 */
export function invoiceTotals(invoice) {
  if (!invoice || typeof invoice !== 'object' || !Array.isArray(invoice.lines)) {
    return fail('INVALID_INVOICE');
  }

  let subtotal = 0;
  let discount = 0;
  let vat = 0;

  for (const line of invoice.lines) {
    if (!line || typeof line !== 'object' || typeof line.qty !== 'number' || typeof line.unitPrice !== 'number') {
      return fail('INVALID_LINE');
    }

    const lineamt = lineTotal(line);
    subtotal += lineamt;

    const discountPercent = line.discountPercent ?? 0;
    const lineDiscount = roundCents(lineamt * discountPercent / 100);
    discount += lineDiscount;

    const lineAmountAfterDiscount = lineamt - lineDiscount;
    const vatRate = line.vatRate ?? 0;
    const lineVAT = roundCents(lineAmountAfterDiscount * vatRate / 100);
    vat += lineVAT;
  }

  const total = Math.max(0, subtotal - discount + vat);
  return ok({ subtotal, discount, vat, total });
}

/**
 * Add a line to an invoice. If the SKU already exists, increase its quantity.
 * @param {{ status: string, customerId: string, lines: Array }} invoice
 * @param {{ sku: string, qty: number, discountPercent?: number }} input
 * @returns {{ ok: true, value: { status: string, lines: Array } } | { ok: false, error: string }}
 */
export function addLine(invoice, input) {
  const { sku, qty } = input;

  // Check status is draft
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  // Validate qty is a positive integer
  if (!Number.isInteger(qty) || qty <= 0) return fail('QTY_INVALID');

  // Get customer for tier discount
  const customerResult = getCustomer(invoice.customerId);
  if (!customerResult.ok) return customerResult;
  const customer = customerResult.value;

  // Determine discountPercent: explicit value wins, otherwise use tier discount
  let discount;
  if ('discountPercent' in input) {
    discount = input.discountPercent;
  } else {
    discount = TIER_DISCOUNTS[customer.tier];
  }

  // Validate discount
  if (typeof discount !== 'number' || discount < 0 || discount > 100) {
    return fail('DISCOUNT_INVALID');
  }

  // Get product by SKU
  const productResult = getProduct(sku);
  if (!productResult.ok) return productResult;

  const product = productResult.value;

  // Create new lines array
  const newLines = [];
  let found = false;

  for (const line of invoice.lines) {
    if (line.sku === sku) {
      newLines.push({
        ...line,
        qty: line.qty + qty,
        discountPercent: discount,
      });
      found = true;
    } else {
      newLines.push({ ...line });
    }
  }

  // If SKU not found, add new line
  if (!found) {
    newLines.push({
      sku,
      name: product.name,
      qty,
      unitPrice: product.unitPrice,
      vatRate: product.vatRate,
      discountPercent: discount,
    });
  }

  return ok({
    ...invoice,
    lines: newLines,
  });
}

/**
 * Remove a line from an invoice by SKU.
 * @param {{ status: string, lines: Array }} invoice
 * @param {string} sku
 * @returns {{ ok: true, value: { status: string, lines: Array } } | { ok: false, error: string }}
 */
export function removeLine(invoice, sku) {
  // Check status is draft
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  // Find the line
  const lineIndex = invoice.lines.findIndex((l) => l.sku === sku);
  if (lineIndex === -1) return fail('LINE_NOT_FOUND');

  // Check if it would remove the last line
  if (invoice.lines.length === 1) return fail('NO_LINES');

  // Create new lines array without that line
  const newLines = invoice.lines.filter((_, i) => i !== lineIndex);

  return ok({
    ...invoice,
    lines: newLines,
  });
}

/**
 * Issue a draft invoice, assigning it a number and changing status to 'issued'.
 * @param {{ status: string, issueDate: string }} invoice
 * @param {Array<string>} existingNumbers - Array of invoice numbers already in use
 * @returns {{ ok: true, value: { number: string, status: string } } | { ok: false, error: string }}
 */
export function issueInvoice(invoice, existingNumbers) {
  // Check status is draft
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  // Get next invoice number
  const numberResult = nextInvoiceNumber(existingNumbers, invoice.issueDate);
  if (!numberResult.ok) return numberResult;

  const number = numberResult.value;

  // Create new invoice with number and status 'issued'
  return ok({
    ...invoice,
    number,
    status: 'issued',
  });
}

/**
 * Apply a voucher to a draft invoice.
 * @param {{ status: string, voucher?: { code: string, amount: number } }} invoice
 * @param {{ code: string, amount: number }} voucher
 * @returns {{ ok: true, value: { voucher: { code: string, amount: number } } } | { ok: false, error: string }}
 */
export function applyVoucher(invoice, voucher) {
  // Check status is draft
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  // Check voucher doesn't already exist
  if (invoice.voucher) return fail('VOUCHER_EXISTS');

  // Validate amount is positive integer
  const { code, amount } = voucher;
  if (!Number.isInteger(amount) || amount <= 0) {
    return fail('AMOUNT_INVALID');
  }

  // Create new invoice with voucher
  return ok({
    ...invoice,
    voucher: { code, amount },
  });
}

